import chalk, { type ChalkInstance, type ColorSupportLevel } from 'chalk';

import { getRandomText } from './text';

const DEFAULT_CHALK_LEVEL = 3 as ColorSupportLevel;

const isColorSupportLevel = (level: number): level is ColorSupportLevel =>
  [0, 1, 2, 3].includes(level);

const getChalkLevel = (): ColorSupportLevel => {
  const envLevel = process.env['CHALK_LEVEL'];
  if (envLevel) {
    const parsed = Number.parseInt(envLevel, 10);
    if (isColorSupportLevel(parsed)) {
      return parsed;
    }
  }
  return DEFAULT_CHALK_LEVEL;
};

chalk.level = getChalkLevel();

const colors = [
  chalk.red,
  chalk.green,
  chalk.blue,
  chalk.yellow,
  chalk.cyan,
  chalk.magenta,
];

const readonlyColors: readonly ChalkInstance[] = colors;

// biome-ignore lint/suspicious/noControlCharactersInRegex: ignore
const ANSI_ESCAPE_CODE_REGEX = new RegExp(`^(${String.fromCharCode(27)}\\[[0-9;]*m)`);

const defaultColor = chalk.white;
const resetColor = chalk.reset;
const resetColorAnsiEscapeCode = '\u001B[39m';

const getRandomColor = (id = '') => {
  let colorId = id;
  if (!colorId) {
    colorId = getRandomText();
  } else if (colorId === 'no-id') {
    return chalk.white;
  }

  const index =
    colorId.split('').reduce((acc, char) => acc + (char.codePointAt(0) ?? 0), 0) %
    colors.length;

  return colors[index];
};

const getNextRandomColor = (
  id: string,
  previousColor: any
) => {
  let colorId = id;
  if (!colorId) {
    colorId = getRandomText();
  }

  const nextColor = getRandomColor(colorId);

  if (
    !previousColor ||
    nextColor.level !== previousColor.level
  ) {
    return { nextColor, previousColor };
  }

  const previousColorIndex = readonlyColors.indexOf(previousColor);

  const nextColorIndex = (previousColorIndex + 1) % colors.length;

  return { nextColor: colors[nextColorIndex], previousColor };
};

const getAnsiEscapeCodes = (colorFunction: (text: string) => string) => {
  const testString = getRandomText();
  const coloredString = colorFunction(testString);

  const escapeCodeMatch = coloredString.match(ANSI_ESCAPE_CODE_REGEX);

  if (escapeCodeMatch) {
    return {
      close: resetColorAnsiEscapeCode,
      open: escapeCodeMatch[0],
    };
  }

  return { close: '', open: '' };
};

export {
  colors,
  defaultColor,
  getAnsiEscapeCodes,
  getNextRandomColor,
  getRandomColor,
  resetColor,
  resetColorAnsiEscapeCode,
};
