    fs.writeFileSync(filePath, content || '', options);
  }
};

const deletePath = (params: Readonly<{
  force?: boolean;
  path: string;
  recursive?: boolean;
  throwError?: boolean;
}>): void => {
  const {
    force = true,
    path: targetPath,
    recursive = true,
    throwError = true,
  } = params;
  const exists = pathExists(targetPath);
  if (!exists && throwError && !force) {
    throw new Error(`Path does not exist: ${targetPath}`);
  }

  if (exists) {
    const isDir = isDirectory(targetPath);
    if (isDir) {
      fs.rmSync(targetPath, { force, recursive });
    } else {
      fs.unlinkSync(targetPath);
    }
  }
};

const copyPath = (params: Readonly<{
  destinationPath: string;
  force?: boolean;
  recursive?: boolean;
  replace?: boolean;
  sourcePath: string;
  throwError?: boolean;
}>): void => {
  const {
    destinationPath,
    force = true,
    recursive = true,
    replace = false,
    sourcePath,
    throwError = true,
  } = params;
  const sourceExists = pathExists(sourcePath);
  if (!sourceExists && throwError) {
    throw new Error(`Source path does not exist: ${sourcePath}`);
  }

  const destinationExists = pathExists(destinationPath);
  if (destinationExists && throwError) {
    throw new Error(`Destination path already exists: ${destinationPath}`);
  }

  if (
    (sourceExists && !destinationExists) ||
    (sourceExists && destinationExists && replace)
  ) {
    if (replace) {
      deletePath({ force, path: destinationPath, recursive });
    }

    const isDir = isDirectory(sourcePath);
    if (isDir) {
      fs.cpSync(sourcePath, destinationPath, { force, recursive });
    } else {
      fs.copyFileSync(sourcePath, destinationPath);
    }
  }
};

const movePath = (params: Readonly<{
  destinationPath: string;
  force?: boolean;
  recursive?: boolean;
  replace?: boolean;
  sourcePath: string;
  throwError?: boolean;
}>): void => {
  const {
    destinationPath,
    force = true,
    recursive = true,
    replace = false,
    sourcePath,
    throwError = true,
  } = params;
  const sourceExists = pathExists(sourcePath);
  if (!sourceExists && throwError) {
    throw new Error(`Source path does not exist: ${sourcePath}`);
  }

  const destinationExists = pathExists(destinationPath);
  if (destinationExists && throwError) {
    throw new Error(`Destination path already exists: ${destinationPath}`);
  }

  if (
    (sourceExists && !destinationExists) ||
    (sourceExists && destinationExists && replace)
  ) {
    if (replace) {
      deletePath({ force, path: destinationPath, recursive });
    }

    fs.renameSync(sourcePath, destinationPath);
  }
};

const backupPath = (params: Readonly<{
  destinationPath?: string;
  force?: boolean;
  recursive?: boolean;
  replace?: boolean;
  sourcePath: string;
  throwError?: boolean;
}>): void => {
  const {
    destinationPath = '',
    force = true,
    recursive = true,
    replace = false,
    sourcePath,
    throwError = true,
  } = params;
  if (!pathExists(sourcePath)) {
    throw new Error(`Path does not exist: ${sourcePath}`);
  }

  const backupDirName = path.dirname(sourcePath);
  const backupBaseName = `${path.basename(sourcePath)}.${Date.now()}.bak`;
  const resolvedBackupPath = path.resolve(
    destinationPath || path.join(backupDirName, backupBaseName)
  );

  if (pathExists(resolvedBackupPath) && throwError) {
    throw new Error(`Backup file already exists: ${resolvedBackupPath}`);
  }

  createDir({
    path: path.dirname(resolvedBackupPath),
    recursive,
  });

  copyPath({
    destinationPath: resolvedBackupPath,
    force,
    recursive,
    replace,
    sourcePath,
  });
};

export {
  backupPath,
  copyPath,
  createDir,
  createFile,
  deletePath,
  findProjectRoot,
  getCallerDir,
  getCallerFile,
  getFileName,
  getImporterDir,
  getImporterFile,
  getProjectRoot,
  getScriptDir,
  getScriptFile,
  isDirectory,
  movePath,
  pathExists,
  readFile,
};
