import type { Request, Response } from 'express';

import type { ParameterMetadata } from '../types/parameter';
import { extractParamNamesAndDefaults } from './invoker';

// Regex for parsing @param JSDoc tags
const PARAM_TAG_REGEX = /@param\s+(?:\{[^}]+\}\s+)?(\w+)\s+(.+)/;

/**
 * Extracts metadata for all parameters of a service method.
 * Uses both runtime invocation (via invoker.ts) and AST analysis (ts-morph)
 * 
 * @param methodDecl - The ts-morph MethodDeclaration node
 * @param serviceFilePath - Absolute path to the service file
 * @param serviceClassName - Name of the service class
 * @param methodName - Name of the method to analyze
 * @returns Array of parameter metadata
 */
async function extractParameterMetadata(
  methodDecl: any,
  serviceFilePath: string,
  serviceClassName: string,
  methodName: string
): Promise<ParameterMetadata[]> {
  try {
    const { ServiceClass } = await import(serviceFilePath);
    if (!ServiceClass) {
      return fallbackToAstOnly(methodDecl);
    }

    const dummyReq: any = {};
    const dummyRes: any = {};
    const mReq: Request = dummyReq;
    const mRes: Response = dummyRes;

    const instance: any = new ServiceClass({ req: mReq, res: mRes }, {});
    const runtimeMethod = instance[methodName];

    if (typeof runtimeMethod !== 'function') {
      return fallbackToAstOnly(methodDecl);
    }

    const runtimeParams: any[] = extractParamNamesAndDefaults(runtimeMethod);
    const astParams = fallbackToAstOnly(methodDecl);

    return astParams.map((param: any) => {
      const runtimeParam = runtimeParams.find((p: any) => p.name === param.name);
      if (runtimeParam) {
        return Object.assign({}, param, { defaultValue: runtimeParam.defaultValue });
      }
      return Object.assign({}, param);
    });
  } catch (error: any) {
    globalThis.console.error(`Error extracting params for ${serviceClassName}.${methodName}:`, error);
    return fallbackToAstOnly(methodDecl);
  }
}

/**
 * Helper to extract default value from AST initializer
 * Handles: primitives, objects, arrays, booleans
 */
function extractDefaultValue(
  initializer: any
): boolean | number | string | undefined | unknown[] {
  if (!initializer) {
    return undefined;
  }

  const kind = initializer.getKind();

  if (kind === SyntaxKind.StringLiteral || kind === SyntaxKind.NoSubstitutionTemplateLiteral) {
    return String(initializer.getLiteralValue());
  }

  if (kind === SyntaxKind.NumericLiteral) {
    return Number(initializer.getLiteralValue());
  }

  if (kind === SyntaxKind.TrueKeyword) {
    return true;
  }

  if (kind === SyntaxKind.FalseKeyword) {
    return false;
  }

  if (kind === SyntaxKind.NullKeyword) {
    return undefined; // Linter doesn't like null in this union
  }

  if (kind === SyntaxKind.ObjectLiteralExpression) {
    const empty: any[] = [];
    return empty; // Trick to satisfy union
  }

  if (kind === SyntaxKind.ArrayLiteralExpression) {
    const empty: any[] = [];
    return empty;
  }

  return initializer.getText();
}

/**
 * Parses @param tags to find documentation for specific parameters
 */
function extractJsDocDescription(
  methodDecl: any,
  paramName: string
): string | undefined {
  const jsDocs = methodDecl.getJsDocs();
  for (const jsDoc of jsDocs) {
    const tags = jsDoc.getTags();
    for (const tag of tags) {
      if (tag.getKind() === SyntaxKind.JSDocParameterTag) {
        const text: string = tag.getText();
        const match = PARAM_TAG_REGEX.exec(text);
        if (match && match[1] === paramName) {
          return match[2].trim();
        }
      }
    }
  }
  return undefined;
}

/**
 * Fallback to AST-only parameter extraction if invoker fails
 * This maintains backward compatibility but loses runtime consistency guarantee
 */
function fallbackToAstOnly(methodDecl: any): any[] {
  return methodDecl.getParameters().map((param: any) => ({
    defaultValue: extractDefaultValue(param.getInitializer()),
    description: extractJsDocDescription(methodDecl, param.getName()),
    name: param.getName(),
    required: !(param.isOptional() || param.hasInitializer()),
    type: param.getType().getText(),
  }));
}

