  '_readableState',
  '_writableState',
  'parser',
  'socket',
]);

const isRecord = (val: unknown): val is Record<string, unknown> =>
  typeof val === 'object' && val !== null && !Array.isArray(val);

const safeSerialize = (value: unknown, ignoredKeys?: readonly string[]): unknown => {
  const seen = new WeakSet();

  if (ignoredKeys) {
    for (const key of ignoredKeys) {
      IGNORED_KEYS.add(key);
    }
  }

  return JSON.parse(
    JSON.stringify(value, (key, val) => {
      if (IGNORED_KEYS.has(key)) {
        return '[Circular]';
      }

      if (val !== undefined && typeof val === 'object') {
        if (seen.has(val)) {
          return '[Circular]';
        }
        seen.add(val);
      }
      return val;
    })
  );
};

// isT removed

const safeClone = <T>(source: T): T => {
  if (source === null || typeof source !== 'object') {
    return source;
  }

  if (Array.isArray(source)) {
    const result: any = source.map(item => safeClone(item));
    return result;
  }

  if (source instanceof Date) {
    const result: any = new Date(source.getTime());
    return result;
  }

  if (isRecord(source)) {
    const result: any = {};
    for (const [key, value] of Object.entries(source)) {
      result[key] = safeClone(value);
    }
    return result;
  }

  return source;
};

